<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import AppModal from '@/components/AppModal.vue'
import {demoMode,request} from '@/services/quality'
const route=useRoute();const platform=computed(()=>route.path.startsWith('/beg'));const journal=computed(()=>route.path.endsWith('/journal'));const prefix=computed(()=>platform.value?'/platform':'/officine')
const exportOpen=ref(false);const exporting=ref(false)
async function exportJournal(){exporting.value=true;error.value='';try{const response=await fetch('/api/v1'+prefix.value+'/journal/export',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json',Authorization:'Bearer '+sessionStorage.getItem('bestpharma.token'),'X-Officine-ID':sessionStorage.getItem('bestpharma.officine')||''},body:JSON.stringify({confirmation:true,...(action.value?{action:action.value}:{}),...(actor.value?{actor:actor.value}:{}),...(from.value?{from:from.value}:{}),...(to.value?{to:to.value}:{})})});if(!response.ok){const d=await response.json();if(d.code==='mfa_enrollment_required')window.location.assign('/dashboard/securite');throw new Error(Object.values(d.errors||{}).flat().join(' ')||d.message||'Export indisponible.')}const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download=platform.value?'journal-plateforme.csv':'journal-officine.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);exportOpen.value=false;await load()}catch(e){error.value=(e as Error).message}finally{exporting.value=false}}
const counts=ref<Record<string,number>>({});const asOf=ref('');const period=ref({from:'',to:''});const days=ref('30');const error=ref('');const busy=ref(false);const rows=ref<Event[]>([]);const page=ref(1);const last=ref(1);const action=ref('');const from=ref('');const to=ref('');const actor=ref('');const selected=ref<Event|null>(null);const open=ref(false)
interface Event {id:number;officine_id:number|null;user_id:number|null;actor:string|null;action:string;created_at:string;result:string;details:Record<string,unknown>}
const labels:Record<string,string>={pending:'Dossiers soumis',under_review:'Dossiers en instruction',corrections_requested:'Corrections attendues',active:'Officines actives',suspended:'Officines suspendues',archived:'Officines archivées',old_pending:'Dossiers anciens en attente',period_submitted:'Dossiers soumis sur la période',members_active:'Membres actifs (comptes actifs)',period_joined:'Appartenances créées sur la période',invitations_pending:'Invitations valides en attente',support_pending:'Propositions encore recevables',support_active:'Accès accompagnateurs actifs',support_expiring:'Accès expirant sous 7 jours'}
async function load(){busy.value=true;error.value='';try{if(journal.value){const query=new URLSearchParams({page:String(page.value)});if(action.value)query.set('action',action.value);if(from.value)query.set('from',from.value);if(to.value)query.set('to',to.value);if(actor.value)query.set('actor',actor.value);const d=await request<{data:Event[];last_page:number}>(prefix.value+'/journal?'+query);rows.value=d.data;last.value=d.last_page}else{const d=await request<{counts:Record<string,number>;as_of:string;period:typeof period.value}>(prefix.value+'/summary?days='+days.value);counts.value=d.counts;asOf.value=d.as_of;period.value=d.period}}catch(e){error.value=(e as Error).message;counts.value={};rows.value=[]}finally{busy.value=false}}
function reset(){page.value=1;load()}
watch(()=>route.path,()=>{page.value=1;action.value='';from.value='';to.value='';actor.value='';open.value=false;exportOpen.value=false;if(!demoMode)load()});onMounted(()=>{if(!demoMode)load()})
</script>
<template><section class="page erp-page"><div class="page-heading compact"><div><p class="eyebrow">MODULE 01 · {{platform?'PLATEFORME':'OFFICINE SÉLECTIONNÉE'}}</p><h1>{{journal?'Journal des accès et décisions':'Tableau des accès'}}</h1><p class="page-subtitle">{{platform?'Métadonnées administratives uniquement. Aucun accès métier implicite.':'Données limitées à votre officine. Administration active requise.'}}</p></div><RouterLink :to="platform?(journal?'/beg/synthese':'/beg/journal'):(journal?'/dashboard/acces':'/dashboard/journal')" class="button secondary">{{journal?'Tableau des accès':'Consulter le journal'}}</RouterLink></div><p v-if="demoMode" class="panel form-body">Ces données serveur sont disponibles dans l’aperçu API. Les exemples du tableau de bord démo restent séparés.</p><template v-else><p v-if="error" class="alert error" role="alert">{{error}}</p><div v-if="journal" class="panel"><form class="form-body form-grid" @submit.prevent="reset"><label>Action exacte<input v-model="action" placeholder="Ex. team.role.saved" maxlength="100"/></label><label>Identifiant de l’acteur<input v-model="actor" type="number" min="1"/></label><label>Du (UTC)<input v-model="from" type="date"/></label><label>Au (UTC)<input v-model="to" type="date" :min="from"/></label><button class="button primary" :disabled="busy">Filtrer le journal</button><button type="button" class="button secondary" :disabled="busy" @click="error='';exportOpen=true">Exporter le journal</button></form><p v-if="busy" role="status" class="form-body">Chargement…</p><div v-else class="table-scroll"><table><thead><tr><th>DATE UTC</th><th>ACTEUR</th><th>ACTION</th><th>OFFICINE</th><th>DÉTAIL</th></tr></thead><tbody><tr v-for="e in rows" :key="e.id"><td>{{e.created_at}}</td><td>{{e.actor||'Système'}} · #{{e.user_id||'—'}}</td><td>{{e.action}}</td><td>{{e.officine_id||'Global'}}</td><td><button class="button secondary small" @click="selected=e;open=true">Voir l’événement</button></td></tr><tr v-if="!rows.length"><td colspan="5" class="empty-state">Aucun événement autorisé pour ces filtres.</td></tr></tbody></table></div><div class="panel-heading"><button class="button secondary" :disabled="busy||page<=1" @click="page--;load()">Précédent</button><span>{{page}} / {{last}}</span><button class="button secondary" :disabled="busy||page>=last" @click="page++;load()">Suivant</button></div><p class="module-disclaimer form-body">Le journal présenté retrace les opérations enregistrées avec succès. Aucun mot de passe, jeton ou contenu de pièce n’est exposé. Export CSV limité à votre périmètre, filtré et journalisé. Aucune purge automatique des données métier n’est activée.</p></div><template v-else><div class="panel form-body"><form class="section-toolbar" @submit.prevent="load"><label>Période des créations et soumissions<select v-model="days"><option value="7">7 derniers jours</option><option value="30">30 derniers jours</option><option value="90">90 derniers jours</option></select></label><button class="button secondary" :disabled="busy">Actualiser</button></form><p class="page-subtitle">Instantané au {{asOf||'—'}}. Les compteurs d’état portent sur tous les enregistrements autorisés à cet instant ; seuls les compteurs « sur la période » utilisent {{period.from}} → {{period.to}}.</p></div><p v-if="busy" role="status">Chargement…</p><div class="stats-grid overview-stats" style="margin-top:20px"><article v-for="(value,key) in counts" :key="key" class="stat-card"><span class="stat-top">{{labels[key]||key}}</span><strong>{{value}}</strong><span class="stat-note">{{String(key).startsWith('period_')?'Période sélectionnée':'État courant autorisé'}}</span></article></div></template></template><AppModal v-model="open" title="Détail de l’événement"><div v-if="selected" class="form-body"><dl class="application-summary"><dt>Événement</dt><dd>#{{selected.id}} · {{selected.action}}</dd><dt>Acteur</dt><dd>{{selected.actor}} · #{{selected.user_id}}</dd><dt>Date UTC</dt><dd>{{selected.created_at}}</dd><dt>Résultat</dt><dd>Opération enregistrée avec succès</dd><dt>Officine</dt><dd>{{selected.officine_id||'Global'}}</dd></dl><pre style="white-space:pre-wrap;overflow-wrap:anywhere">{{JSON.stringify(selected.details,null,2)}}</pre></div><template #footer><button class="button secondary" @click="open=false">Fermer</button></template></AppModal><AppModal v-model="exportOpen" title="Exporter le journal autorisé ?" :busy="exporting"><div class="form-body"><p v-if="error" class="alert error" role="alert">{{error}}</p><p>L’export CSV utilise les filtres actuellement sélectionnés, sur toutes les pages, dans la limite de 5 000 événements. Aucun export partiel n’est produit au-delà de cette limite. L’opération sera journalisée.</p><p>Le fichier peut contenir des identités et métadonnées administratives autorisées. Conservez-le dans un emplacement sécurisé. Aucun secret ni contenu de pièce n’est exporté.</p></div><template #footer><button class="button secondary" :disabled="exporting" @click="exportOpen=false">Annuler</button><button class="button primary" :disabled="exporting" @click="exportJournal">Confirmer l’export CSV</button></template></AppModal></section></template>
